// Excel workbook for a report. Each sheet has a details block (shop,
// report, period, filters, generated by/at), then each section: a band
// title, a header row, typed data cells and a bold totals row.
//
// Numbers and dates are stored as values with number formats, so the
// workbook can be sorted and summed. Totals are the spec's own values
// (the screen's totals), not formulas.

import 'dart:math' as math;

import 'package:stockall/pages/report/components/export/report_export_format.dart';
import 'package:stockall/pages/report/components/export/report_export_resolve.dart';
import 'package:stockall/pages/report/components/export/report_export_spec.dart';
import 'package:syncfusion_flutter_xlsio/xlsio.dart';

const String _headerFill = '#F2F2F2';
const String _bandFill = '#E7E7E7';
const String _totalFill = '#F2F2F2';

/// Excel column widths, in characters.
const double _minColumnWidth = 10;
const double _maxColumnWidth = 50;

/// The workbook bytes for [wb] (see resolveWorkbook).
List<int> buildReportWorkbook(ResolvedWorkbook wb) {
  final workbook = Workbook(wb.sheets.length);
  try {
    for (var i = 0; i < wb.sheets.length; i++) {
      final sheet = workbook.worksheets[i];
      _writeSheet(sheet, wb, wb.sheets[i]);
    }
    return workbook.saveAsStream();
  } finally {
    workbook.dispose();
  }
}

void _writeSheet(Worksheet sheet, ResolvedWorkbook wb, ResolvedSheet s) {
  sheet.name = s.name;
  final meta = wb.meta;
  final f = ExportFormatter(currency: meta.context.currencySymbol);

  var row = 1;
  void line(String text, {bool bold = false, double? size}) {
    final r = sheet.getRangeByIndex(row, 1);
    r.setText(text);
    if (bold) r.cellStyle.bold = true;
    if (size != null) r.cellStyle.fontSize = size;
    row++;
  }

  line(meta.context.shopName, bold: true, size: 14);
  line(meta.reportName, bold: true, size: 12);
  if (s.groupName != null && wb.splitLabel != null) {
    line('${wb.splitLabel}: ${s.groupName}', bold: true);
  }
  line('Period: ${meta.periodLabel ?? 'All time'}');
  line('Filters: ${meta.filtersText}');
  if (meta.sortedBy != null) line('Sorted by: ${meta.sortedBy}');
  if (meta.groupedBy != null) line('Grouped by: ${meta.groupedBy}');
  for (final n in meta.notes) {
    line('Notes: $n');
  }
  line(
    'Generated by ${meta.context.generatedBy} on '
    '${f.dateTime(meta.context.generatedAt)}',
  );
  row++; // blank line

  // Widths follow the widest section on the sheet.
  final widths = <int, double>{};
  var firstTable = true;

  for (final section in s.sections) {
    if (section is ResolvedTable) {
      row = _writeTable(
        sheet,
        section,
        row,
        wb.meta.context.currencySymbol,
        widths,
        filterAndFreeze: firstTable,
      );
      firstTable = false;
    } else if (section is ResolvedSummary) {
      row = _writeSummary(
        sheet,
        section,
        row,
        wb.meta.context.currencySymbol,
        widths,
      );
    }
    row++; // blank line between sections
  }

  widths.forEach((col, width) {
    sheet.getRangeByIndex(1, col).columnWidth = width;
  });
}

void _band(Worksheet sheet, int row, int columns, String title) {
  final range = sheet.getRangeByIndex(row, 1, row, math.max(1, columns));
  if (columns > 1) range.merge();
  final first = sheet.getRangeByIndex(row, 1);
  first.setText(title);
  range.cellStyle.bold = true;
  range.cellStyle.backColor = _bandFill;
  range.cellStyle.hAlign = HAlignType.center;
  range.cellStyle.borders.all.lineStyle = LineStyle.thin;
}

void _fitWidth(Map<int, double> widths, int col, String text) {
  final longest = text
      .split('\n')
      .fold<int>(0, (m, l) => math.max(m, l.length));
  final width = (longest + 2)
      .toDouble()
      .clamp(_minColumnWidth, _maxColumnWidth);
  if (width > (widths[col] ?? 0)) widths[col] = width;
}

int _writeTable(
  Worksheet sheet,
  ResolvedTable t,
  int startRow,
  String currency,
  Map<int, double> widths, {
  required bool filterAndFreeze,
}) {
  // Roll-only columns are left out.
  final idx = t.excelColumnIndexes;
  final cols = idx.length;
  var row = startRow;

  _band(sheet, row, cols, t.title);
  row++;

  final headerRow = row;
  for (var c = 0; c < cols; c++) {
    final col = t.columns[idx[c]];
    sheet.getRangeByIndex(row, c + 1).setText(col.label);
    _fitWidth(widths, c + 1, col.label);
  }
  final header = sheet.getRangeByIndex(row, 1, row, cols);
  header.cellStyle.bold = true;
  header.cellStyle.backColor = _headerFill;
  header.cellStyle.borders.all.lineStyle = LineStyle.thin;
  header.cellStyle.vAlign = VAlignType.center;
  row++;

  if (t.isEmpty) {
    final r = sheet.getRangeByIndex(row, 1);
    r.setText(t.emptyMessage);
    r.cellStyle.italic = true;
    return row + 1;
  }

  final firstData = row;
  for (final cells in t.rows) {
    for (var c = 0; c < cols; c++) {
      final i = idx[c];
      _writeCell(
        sheet.getRangeByIndex(row, c + 1),
        cells[i],
        t.columns[i],
        currency,
      );
      _fitWidth(widths, c + 1, cells[i].text);
    }
    row++;
  }
  final lastData = row - 1;
  sheet
      .getRangeByIndex(firstData, 1, lastData, cols)
      .cellStyle
      .borders
      .all
      .lineStyle = LineStyle.thin;

  if (filterAndFreeze) {
    sheet.autoFilters.filterRange = sheet.getRangeByIndex(
      headerRow,
      1,
      lastData,
      cols,
    );
    sheet.getRangeByIndex(headerRow + 1, 1).freezePanes();
  }

  if (t.totals != null) {
    for (var c = 0; c < cols; c++) {
      final cell = t.totals![idx[c]];
      final range = sheet.getRangeByIndex(row, c + 1);
      if (c == 0 && (cell.raw == null || cell.raw is String)) {
        final text = cell.text.isEmpty
            ? t.totalsLabel
            : '${t.totalsLabel} (${cell.text})';
        range.setText(text);
        _fitWidth(widths, 1, text);
      } else {
        _writeCell(range, cell, t.columns[idx[c]], currency);
      }
    }
    final totals = sheet.getRangeByIndex(row, 1, row, cols);
    totals.cellStyle.bold = true;
    totals.cellStyle.backColor = _totalFill;
    totals.cellStyle.borders.all.lineStyle = LineStyle.thin;
    totals.cellStyle.borders.top.lineStyle = LineStyle.medium;
    row++;
  }
  return row;
}

int _writeSummary(
  Worksheet sheet,
  ResolvedSummary s,
  int startRow,
  String currency,
  Map<int, double> widths,
) {
  final notes = s.hasNotes;
  final cols = notes ? 3 : 2;
  var row = startRow;

  _band(sheet, row, cols, s.title);
  row++;

  final labels = ['Metric', 'Value', if (notes) 'Change'];
  for (var c = 0; c < labels.length; c++) {
    sheet.getRangeByIndex(row, c + 1).setText(labels[c]);
  }
  final header = sheet.getRangeByIndex(row, 1, row, cols);
  header.cellStyle.bold = true;
  header.cellStyle.backColor = _headerFill;
  header.cellStyle.borders.all.lineStyle = LineStyle.thin;
  row++;

  final first = row;
  for (final m in s.metrics) {
    sheet.getRangeByIndex(row, 1).setText(m.label);
    _fitWidth(widths, 1, m.label);
    _writeValue(
      sheet.getRangeByIndex(row, 2),
      m.raw,
      m.text,
      m.format,
      currency,
    );
    _fitWidth(widths, 2, m.text);
    if (notes) {
      sheet.getRangeByIndex(row, 3).setText(m.note ?? '');
      _fitWidth(widths, 3, m.note ?? '');
    }
    row++;
  }
  if (row > first) {
    sheet
        .getRangeByIndex(first, 1, row - 1, cols)
        .cellStyle
        .borders
        .all
        .lineStyle = LineStyle.thin;
  }
  return row;
}

void _writeCell(
  Range range,
  ResolvedCell cell,
  ResolvedColumn column,
  String currency,
) {
  _writeValue(range, cell.raw, cell.text, column.format, currency);
}

/// Numbers and dates are written as values with a number format. A text
/// override for a missing value ("N/A") is written as text.
void _writeValue(
  Range range,
  Object? raw,
  String text,
  ExportFormat format,
  String currency,
) {
  if (raw is num && format.isNumeric && raw.isFinite) {
    final value = format == ExportFormat.percent ? raw / 100 : raw;
    range.setNumber(value.toDouble());
    final nf = excelNumberFormat(format, raw, currency: currency);
    if (nf != null) range.numberFormat = nf;
    return;
  }
  if (raw is DateTime && format.isDate) {
    range.setDateTime(raw);
    final nf = excelNumberFormat(format, raw, currency: currency);
    if (nf != null) range.numberFormat = nf;
    return;
  }
  if (text.isNotEmpty) range.setText(text);
}
